th="1.2"></circle><circle cx="105.32909926991846" cy="356.35153980321917" r="6" fill="rgba(197, 154, 69, 0.3)"></circle><circle cx="200" cy="500.00000000000006" r="8" fill="none" stroke="rgba(197, 154, 69, 0.3)" stroke-width="1.2" stroke-dasharray="2 2"></circle><circle cx="769.9707960683465" cy="178.26133389002916" r="6" fill="rgba(197, 154, 69, 0.35)"></circle><g transform="translate(577.6457135307562 789.7777478867205) scale(1.2)" class="sky-star"><path d="M0 -24 L1.4 -1.4 L10 0 L1.4 1.4 L0 24 L-1.4 1.4 L-10 0 L-1.4 -1.4 Z"></path><path d="M-4.5 -4.5 L4.5 4.5 M4.5 -4.5 L-4.5 4.5" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.8"></path></g><g transform="translate(289.9999999999998 136.26933041053582) scale(1.4)" class="sky-star"><path d="M0 -24 L1.4 -1.4 L10 0 L1.4 1.4 L0 24 L-1.4 1.4 L-10 0 L-1.4 -1.4 Z"></path><path d="M-4.5 -4.5 L4.5 4.5 M4.5 -4.5 L-4.5 4.5" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.8"></path></g><g transform="translate(683.5259069949229 549.175618569479) scale(1.1)" class="sky-star"><path d="M0 -24 L1.4 -1.4 L10 0 L1.4 1.4 L0 24 L-1.4 1.4 L-10 0 L-1.4 -1.4 Z"></path><path d="M-4.5 -4.5 L4.5 4.5 M4.5 -4.5 L-4.5 4.5" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.8"></path></g></svg><div class="program-main"><h2 id="program-title">Personalised Hand Holding Program</h2><p>Knowing what to change is one part of it. Following through takes time. Work with Narayani over six months, with space to ask, reflect and try again.</p><div class="cta-row"><a href="/contact/?topic=the%20Personalised%20Hand%20Holding%20Program" class="button button-light" data-enquiry="" data-topic="the Personalised Hand Holding Program" data-source="home-program" aria-haspopup="dialog">Enquire about the program</a><a class="program-btn-learn" href="/hand-holding-program/">How the six months work →</a></div><p class="program-note">Format and fees are discussed before you decide.</p></div><div class="program-details"><div class="program-duration"><strong>6</strong><span>months of personal guidance</span></div><ul><li>Calls and messages through the six months</li><li>Space to revisit, reflect and ask</li><li>All four areas, together</li></ul><div class="program-domains"><span>Health</span><span>Relationship</span><span>Career</span><span>Money</span></div></div></div></section><section class="faq-wrap has-backdrop" aria-labelledby="faq-title"><svg class="backdrop backdrop-vastu " viewBox="0 0 300 300" aria-hidden="true" focusable="false"><rect x="30" y="30" width="240" height="240" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="1.1"></rect><path d="M56.66666666666667 30V270M30 56.66666666666667H270M83.33333333333334 30V270M30 83.33333333333334H270M110 30V270M30 110H270M136.66666666666669 30V270M30 136.66666666666669H270M163.33333333333334 30V270M30 163.33333333333334H270M190 30V270M30 190H270M216.66666666666669 30V270M30 216.66666666666669H270M243.33333333333334 30V270M30 243.33333333333334H270" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.7" class="sky-faint"></path><rect x="110" y="110" width="80" height="80" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="1.1"></rect><circle cx="150" cy="150" r="4" class="sky-ink"></circle><text x="150" y="14" class="sky-direction" text-anchor="middle" dominant-baseline="central">N</text><text x="282" y="18" class="sky-direction" text-anchor="middle" dominant-baseline="central">NE</text><text x="288" y="150" class="sky-direction" text-anchor="middle" dominant-baseline="central">E</text><text x="282" y="284" class="sky-direction" text-anchor="middle" dominant-baseline="central">SE</text><text x="150" y="288" class="sky-direction" text-anchor="middle" dominant-baseline="central">S</text><text x="18" y="284" class="sky-direction" text-anchor="middle" dominant-baseline="central">SW</text><text x="12" y="150" class="sky-direction" text-anchor="middle" dominant-baseline="central">W</text><text x="18" y="18" class="sky-direction" text-anchor="middle" dominant-baseline="central">NW</text></svg><div class="faq section-wrap section-space" id="faq"><div class="faq-intro"><h2 id="faq-title">Before you enquire</h2><p>A few things you may want to know first.</p><a href="/contact/" class="text-link" data-enquiry="" data-source="home-faq" aria-haspopup="dialog">Ask something else</a></div><div class="faq-list"><details><summary>Where should I begin?<span aria-hidden="true"></span></summary><p>With the question on your mind, not with a service. Send a WhatsApp message, call, or leave your number, and the team explains the options, fees and next steps before you book.</p></details><details><summary>How is a consultation different from the program?<span aria-hidden="true"></span></summary><p>A consultation is a focused conversation around a question or a concern. The Personalised Hand Holding Program extends the guidance over six months, with calls and messages as you work through different areas of life.</p></details><details><summary>Can I enquire if I live outside India?<span aria-hidden="true"></span></summary><p>Yes. Mention your country and time zone when you enquire so the team can arrange an online consultation that suits you.</p></details><details><summary>What are the consultation and program fees?<span aria-hidden="true"></span></summary><p>Please ask for the current fees when you enquire. The consultation and the six-month program are separate options, and the team explains the scope and the fee before you decide.</p></details><details><summary>Does this replace medical or professional advice?<span aria-hidden="true"></span></summary><p>No. This is personal and spiritual guidance. It does not replace medical care, mental health treatment, legal advice or financial advice from qualified professionals.</p></details></div></div></section><section c